package com.example.starter.translation.config;

import com.fasterxml.jackson.core.SerializableString;
import com.fasterxml.jackson.core.io.CharacterEscapes;
import com.fasterxml.jackson.core.io.SerializedString;

/**
 * JSON 字符转义：将双向控制符（U+202A~U+202E、U+2066~U+2069）序列化为 \uXXXX 转义形式，
 * 仅改变 JSON 展示形式，解析后文本码点不变。
 */
public class BidiCharacterEscapes extends CharacterEscapes {

    private final int[] escapeCodes;

    public BidiCharacterEscapes() {
        int[] codes = new int[0x2070];
        for (int cp = 0x202A; cp <= 0x202E; cp++) {
            codes[cp] = ESCAPE_CUSTOM;
        }
        for (int cp = 0x2066; cp <= 0x2069; cp++) {
            codes[cp] = ESCAPE_CUSTOM;
        }
        this.escapeCodes = codes;
    }

    @Override
    public int[] getEscapeCodesForCharacters() {
        return escapeCodes;
    }

    @Override
    public SerializableString getEscapeSequence(int ch) {
        return new SerializedString("\\u" + String.format("%04X", ch));
    }
}
```

