package com.example.starter.translation.config;

import com.fasterxml.jackson.core.SerializableString;
import com.fasterxml.jackson.core.io.CharacterEscapes;
import com.fasterxml.jackson.core.io.SerializedString;

/**
 * JSON 字符转义：将双向控制符（U+202A~U+202E、U+2066~U+2069）序列化为 �XXXX 转义形式。
 * 仅改变接口 JSON 的展示形式，解析后文本码点与原文完全一致，不改变文本本身。
 */
public class BidiCharacterEscapes extends CharacterEscapes {

    private final int[] escapeCodes;

    public BidiCharacterEscapes() {
        int[] codes = new int[0x2070];
        for (int cp = 0x202A; cp <= 0x202E; cp++) {
            codes[cp] = ESCAPE_CUSTOM;
        }
        for (int cp = 0x2066; cp <= 0x2069; cp++) {
            codes[cp] = ESCAPE_CUSTOM;
        }
        this.escapeCodes = codes;
    }

    @Override
    public int[] getEscapeCodesForCharacters() {
        return escapeCodes;
    }

    @Override
    public SerializableString getEscapeSequence(int ch) {
        return new SerializedString("\\u" + String.format("%04X", ch));
    }
}

package com.example.starter.translation.config;

import com.fasterxml.jackson.core.JsonFactory;
import org.springframework.boot.autoconfigure.jackson.Jackson2ObjectMapperBuilderCustomizer;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * Jackson 配置：接口 JSON 输出对双向控制符使用 �XXXX 转义展示，不改变文本内容。
 */
@Configuration
public class JacksonConfig {

    /** 为主 ObjectMapper 配置双向控制符转义的 JsonFactory。 */
    @Bean
    public Jackson2ObjectMapperBuilderCustomizer bidiControlCharacterEscapes() {
        JsonFactory factory = JsonFactory.builder().build()
                .setCharacterEscapes(new BidiCharacterEscapes());
        return builder -> builder.factory(factory);
    }
}

