        assertThat(BidiIsolateValidator.findErrorIndex(LRI + LRI + LRI + LRI + LRI)).isEqualTo(4);
        assertThat(BidiIsolateValidator.findErrorIndex("ab" + LRI + LRI + LRI + LRI + LRI)).isEqualTo(6);
